   113→      JSON.parse(fs.readFileSync(transcriptPath, "utf8")).fullText?.length > 0;
   114→
   115→    if (transcriptExists) {
   116→      logger.info({ uploadId }, "Transcript already exists — skipping transcription");
   117→      writeStatus(uploadId, { status: "processing", step: "transcribing", startedAt: new Date().toISOString() });
   118→    } else {
   119→      writeStatus(uploadId, { status: "processing", step: "transcribing", startedAt: new Date().toISOString() });
   120→      logger.info({ uploadId }, "Starting transcription");
   121→      const { stdout: transcriptOut, stderr: transcriptErr } = await runPython("transcribe.py", [
   122→        audioPath,
   123→        transcriptPath,
   124→        process.env.WHISPER_MODEL || "small",
   125→      ]);
   126→      if (transcriptErr) logger.warn({ stderr: transcriptErr }, "Transcription stderr");
   127→      const transcriptResult = JSON.parse(transcriptOut.trim());
   128→      if (transcriptResult.error) throw new Error(`Transcription failed: ${transcriptResult.error}`);
   129→    }
   130→
   131→    // Step 2: Speaker diarization (skip if diarization output already exists)
   132→    let hasDiarization = false;
   133→    let diarizationData: any = null;
