   135→
   136→    if (hfToken && diarizationExists) {
   137→      logger.info({ uploadId }, "Diarization already exists — skipping diarization");
   138→      diarizationData = JSON.parse(fs.readFileSync(diarizationPath, "utf8"));
   139→      hasDiarization = true;
   140→    } else if (hfToken) {
   141→      writeStatus(uploadId, { status: "processing", step: "diarizing", startedAt: new Date().toISOString() });
   142→      logger.info({ uploadId }, "Starting speaker diarization");
   143→      try {
