   165→    // Step 3: Audio analysis
   166→    writeStatus(uploadId, { status: "processing", step: "analyzing", startedAt: new Date().toISOString() });
   167→    logger.info({ uploadId }, "Starting audio analysis");
   168→    const { stdout: metricsOut, stderr: metricsErr } = await runPython("analyze_audio.py", [
   169→      audioPath,
   170→      transcriptPath,
   171→      metricsPath,
