   329→    fillerWords: t.fillerWords,
   330→  });
   331→});
   332→
   333→// GET /api/report/:id
   334→router.get("/report/:id", (req, res) => {
   335→  const report = loadReport(req.params.id);
   336→  if (!report) {
   337→    res.status(404).json({ error: "Report not found" });
   338→    return;
   339→  }
   340→  res.json(report);
   341→});
   342→
   343→// GET /api/download-pdf/:id
   344→router.get("/download-pdf/:id", (req, res) => {
   345→  const { id } = req.params;
   346→  const pdfPath = path.join(REPORTS_DIR, `${id}.pdf`);
   347→  if (!fs.existsSync(pdfPath)) {
   348→    res.status(404).json({ error: "PDF not found. Run analysis first." });
   349→    return;
   350→  }
   351→  res.setHeader("Content-Type", "application/pdf");
   352→  res.setHeader("Content-Disposition", `attachment; filename="report-${id}.pdf"`);
   353→  fs.createReadStream(pdfPath).pipe(res as any);
   354→});
   355→
   356→// GET /api/analyses
   357→router.get("/analyses", (req, res) => {
   358→  if (!fs.existsSync(REPORTS_DIR)) {
   359→    res.json([]);
   360→    return;
   361→  }
   362→  const files = fs.readdirSync(REPORTS_DIR).filter((f) => f.endsWith(".json"));
   363→  const summaries = files
   364→    .map((f) => {
   365→      try {
   366→        const r = JSON.parse(fs.readFileSync(path.join(REPORTS_DIR, f), "utf8"));
   367→        return {
   368→          id: r.id,
   369→          date: r.date,
   370→          filename: r.filename,
   371→          durationSeconds: r.metrics?.durationSeconds ?? 0,
   372→          overallEngagement: r.indicators?.engagement?.classification ?? "Unknown",
   373→          pdfAvailable: r.pdfAvailable ?? false,
   374→          hasDiarization: r.hasDiarization ?? false,
   375→          speakerCount: Object.keys(r.speakers || {}).length,
   376→        };
   377→      } catch {
   378→        return null;
   379→      }
   380→    })
   381→    .filter(Boolean)
   382→    .sort((a: any, b: any) => new Date(b.date).getTime() - new Date(a.date).getTime());
   383→
   384→  res.json(summaries);
   385→});
